import {dateNumber, todayISO, weekdaysBetween, projectPeriod} from './planning.js?v=3';
export const DAY=86400000;
export const round=n=>Math.round((n+Number.EPSILON)*100)/100;
export const sum=values=>round(values.reduce((s,n)=>s+n,0));
export const uuid=()=>globalThis.crypto.randomUUID();
export const copy=x=>structuredClone(x);
export const STATUSES={to_send:'À envoyer',to_correct:'À corriger',sent:'Envoyée',awaiting_payment:'En attente de paiement',paid:'Payée'};
export const DEFAULT_CATEGORIES=[['salaries','Salaire net','#365d4b'],['flights','Voyages / billets','#798fb1'],['lodging','Logement / transport','#a2ad7c'],['taxes','Taxes et contributions','#c1a16a'],['contractors','Prestataires / frais locaux','#8b94aa'],['expenses','Notes de frais','#b297a8'],['contingency','Imprévus','#c29b7c'],['other','Autres','#9ca79b']].map(([id,name,color])=>({id,name,color}));
export function iso(n){return new Date(n).toISOString().slice(0,10);}
export function plusDays(date,n){return iso(dateNumber(date)+n*DAY);}
export function endOfYear(date){const d=new Date(dateNumber(date));d.setUTCFullYear(d.getUTCFullYear()+1);return iso(d.getTime()-DAY);}
export function datesBetween(start,end){const a=dateNumber(start),b=dateNumber(end);if(!Number.isFinite(a)||!Number.isFinite(b)||b<a||b-a>3660*DAY)return [];return Array.from({length:Math.floor((b-a)/DAY)+1},(_,i)=>iso(a+i*DAY));}
const amount=n=>Number.isFinite(n)&&Math.abs(n)<=1e10;
const nonnegative=n=>amount(n)&&n>=0;
const validDate=d=>Number.isFinite(dateNumber(d));
const text=(s,max=200)=>typeof s==='string'&&s.length<=max;
export function newItem(extra={}){return {id:uuid(),name:'Nouveau coût',categoryId:'other',amount:0,currency:'EUR',frequency:'once',quantity:1,referenceDays:200,date:'',enabled:true,taxed:false,buffered:false,...extra};}
export function newBudget(){const start=todayISO();return {name:'Budget de référence',startDate:start,endDate:endOfYear(start),daysOverride:null,offDays:0,extraDays:0,netDayRate:0,markupPct:0,usdPerEur:1,useBudgetFx:false,budgetEurPerUsd:1,vatRate:0,safetyMode:'none',safetyRate:0,notes:'',items:[]};}
export function newProject(){return {version:4,id:uuid(),name:'Mon projet',client:'',reportDate:todayISO(),categories:copy(DEFAULT_CATEGORIES),salaryCategoryId:'salaries',budget:newBudget(),consultants:[],actualExpenses:[],invoices:[],legacy:null};}
export function newConsultant(p){return {id:uuid(),name:'Nouveau consultant',role:'',startDate:p.budget.startDate,endDate:p.budget.endDate,daysOverride:null,offDays:0,extraDays:0,netDayRate:null,markupPct:null,sellingDayRate:0,overtimeHours:0,overtimeSellingRate:0,overtimeCostRate:0,customBudget:null,extras:[],baseline:null,archived:false};}
export function billableDays(c){const weekdays=weekdaysBetween(dateNumber(c.startDate),dateNumber(c.endDate));return Math.max(0,c.daysOverride===null?weekdays-c.offDays+c.extraDays:c.daysOverride);}
export function profileFor(p,c){const profile=copy(c.customBudget||p.budget);if(c.netDayRate!==null)profile.netDayRate=c.netDayRate;if(c.markupPct!==null)profile.markupPct=c.markupPct;return profile;}
function fx(b,currency){return currency==='USD'?(b.useBudgetFx?b.budgetEurPerUsd:1/b.usdPerEur):1;}
function weightedDates(c){const dates=datesBetween(c.startDate,c.endDate),days=billableDays(c);const weekdays=dates.filter(d=>![0,6].includes(new Date(dateNumber(d)).getUTCDay()));const weekends=dates.filter(d=>[0,6].includes(new Date(dateNumber(d)).getUTCDay()));if(c.daysOverride!==null){const anchors=weekdays.length?weekdays:dates;return anchors.map(date=>({date,weight:anchors.length?days/anchors.length:0}));}return [...weekdays.map(date=>({date,weight:weekdays.length?(weekdays.length-c.offDays)/weekdays.length:0})),...weekends.map(date=>({date,weight:weekends.length?c.extraDays/weekends.length:0}))].filter(x=>x.weight>0).sort((a,b)=>a.date.localeCompare(b.date));}
function allocateCents(total,weights){const cents=Math.round(total*100),weight=weights.reduce((s,w)=>s+w.weight,0);if(!weight||!weights.length)return [];let cumulative=0,allocated=0;return weights.map(w=>{cumulative+=w.weight;const target=Math.round(cents*cumulative/weight),value=(target-allocated)/100;allocated=target;return {date:w.date,cost:value};});}
function monthWeight(date){const d=new Date(dateNumber(date));return 1/new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();}
export function planPerson(c,b,salaryCategoryId='salaries'){
 const days=billableDays(c),weighted=weightedDates(c),calendar=datesBetween(c.startDate,c.endDate),items=[];
 function addItem(item,total,weights,source){const timeline=allocateCents(round(total),weights);items.push({...item,total:round(total),rawTotal:total,_weights:weights,timeline,source});}
 addItem({id:'salary',name:'Salaire net',categoryId:salaryCategoryId},days*b.netDayRate,weighted,'salary');
 for(const [source,lines]of [['base',b.items],['extra',c.extras]])for(const item of lines.filter(i=>i.enabled)){
   let base=0,weights=weighted;const unit=item.amount*item.quantity*fx(b,item.currency);
   if(item.frequency==='day')base=unit*days;
   if(item.frequency==='amortized')base=unit*days/item.referenceDays;
   if(item.frequency==='month'){weights=calendar.map(date=>({date,weight:monthWeight(date)}));base=unit*weights.reduce((s,w)=>s+w.weight,0);}
   if(item.frequency==='once'){base=unit;weights=[{date:item.date||c.startDate,weight:1}];}
   if(item.frequency==='salary_pct')base=b.netDayRate*days*item.amount*item.quantity/100;
   const vat=item.taxed?base*b.vatRate/100:0;
   const safety=item.buffered&&b.safetyMode==='add'?(base+vat)*b.safetyRate/100:0;
   addItem({...item,base:round(base),vat:round(vat),safety:round(safety)},base+vat+safety,weights,source);
 }
 if(c.overtimeCostRate*c.overtimeHours)addItem({id:'overtime',name:'Coût des heures supplémentaires',categoryId:salaryCategoryId},c.overtimeCostRate*c.overtimeHours,weighted.length?weighted:calendar.map(date=>({date,weight:1})),'overtime');
 const targetTotal=round(items.reduce((s,i)=>s+i.rawTotal,0)),roundingGap=round(targetTotal-sum(items.map(i=>i.total)));if(roundingGap&&items.length){const largest=items.reduce((a,b)=>a.total>=b.total?a:b);largest.total=round(largest.total+roundingGap);largest.timeline=allocateCents(largest.total,largest._weights);}for(const i of items)delete i._weights;
 const totalCost=sum(items.map(i=>i.total)),unitCost=days?totalCost/days:null,targetPrice=unitCost===null?null:round(unitCost*(1+b.markupPct/100));
 const revenue=sum([days*c.sellingDayRate,c.overtimeHours*c.overtimeSellingRate]);
 const byDate=new Map();for(const item of items)for(const row of item.timeline)byDate.set(row.date,round((byDate.get(row.date)||0)+row.cost));
 const byCategory={};for(const item of items)byCategory[item.categoryId]=round((byCategory[item.categoryId]||0)+item.total);
 return {startDate:c.startDate,endDate:c.endDate,days,netDayRate:b.netDayRate,markupPct:b.markupPct,sellingDayRate:c.sellingDayRate,totalCost,unitCost:unitCost===null?null:round(unitCost),targetPrice,revenue,margin:round(revenue-totalCost),marginPct:revenue?100*(revenue-totalCost)/revenue:null,items,byCategory,timeline:[...byDate].sort(([a],[b])=>a.localeCompare(b)).map(([date,cost])=>({date,cost}))};
}
export function referenceBudget(p){const b=p.budget,c={...b,sellingDayRate:0,overtimeHours:0,overtimeSellingRate:0,overtimeCostRate:0,extras:[]};return planPerson(c,b,p.salaryCategoryId);}
export function consultantPlan(p,c){return planPerson(c,profileFor(p,c),p.salaryCategoryId);}
export function freezeBaseline(p,c){return {capturedAt:todayISO(),salaryCategoryId:p.salaryCategoryId,profile:profileFor(p,c),consultant:{...copy(c),customBudget:null,baseline:null},categoryNames:Object.fromEntries(p.categories.map(x=>[x.id,x.name]))};}
export function initialPlan(p,c){return c.baseline?planPerson(c.baseline.consultant,c.baseline.profile,c.baseline.salaryCategoryId):consultantPlan(p,c);}
export function invoiceTotal(i){return sum([i.days*i.dayRate,i.overtimeHours*i.hourRate,i.extraHT]);}
export function paymentsAt(i,asOf='2200-12-31'){return sum(i.payments.filter(x=>x.date<=asOf).map(x=>x.amount));}
export function statusAt(i,asOf){if(i.status==='to_send'||i.status==='to_correct')return i.status;if(paymentsAt(i,asOf)>=invoiceTotal(i)-.005&&invoiceTotal(i)>0)return 'paid';return i.status==='paid'?'awaiting_payment':i.status;}
export function billingSummary(p,consultantId,asOf=p.reportDate){const invoices=p.invoices.filter(i=>!consultantId||i.consultantId===consultantId);const issued=invoices.filter(i=>['sent','awaiting_payment','paid'].includes(i.status)&&i.issueDate&&i.issueDate<=asOf);const billed=sum(issued.map(invoiceTotal)),paid=sum(invoices.map(i=>paymentsAt(i,asOf))),days=sum(issued.map(i=>i.days));const outstanding=sum(issued.map(i=>Math.max(0,round(invoiceTotal(i)-paymentsAt(i,asOf)))));return {invoices,issued,billed,paid,days,outstanding,toSend:sum(invoices.filter(i=>i.status==='to_send').map(invoiceTotal)),toCorrect:sum(invoices.filter(i=>i.status==='to_correct').map(invoiceTotal)),overdue:sum(issued.filter(i=>i.dueDate&&i.dueDate<asOf).map(i=>Math.max(0,round(invoiceTotal(i)-paymentsAt(i,asOf))))),forfaitCount:issued.filter(i=>!i.days&&invoiceTotal(i)>0).length};}
function totalUntil(timeline,date){return sum(timeline.filter(x=>x.date<=date).map(x=>x.cost));}
export function consultantDashboard(p,c,asOf=p.reportDate){
 const plan=consultantPlan(p,c),baseline=initialPlan(p,c),billing=billingSummary(p,c.id,asOf),expenses=p.actualExpenses.filter(e=>e.consultantId===c.id&&e.date<=asOf),actual=sum(expenses.map(e=>expenseEUR(p,e))),budgetAtDate=totalUntil(baseline.timeline,asOf);
 const actualByCategory={};for(const e of expenses)actualByCategory[e.categoryId]=round((actualByCategory[e.categoryId]||0)+expenseEUR(p,e));
 const categoryIds=[...new Set([...Object.keys(baseline.byCategory),...Object.keys(plan.byCategory),...Object.keys(actualByCategory)])];
 const categoryRows=categoryIds.map(id=>{const allowed=sum(baseline.items.filter(i=>i.categoryId===id).map(i=>totalUntil(i.timeline,asOf)));return {id,name:p.categories.find(c=>c.id===id)?.name||c.baseline?.categoryNames[id]||'Autres',initial:baseline.byCategory[id]||0,forecast:plan.byCategory[id]||0,budgetAtDate:allowed,actual:actualByCategory[id]||0,gapAtDate:round((actualByCategory[id]||0)-allowed),forecastGap:round((plan.byCategory[id]||0)-(baseline.byCategory[id]||0))};}).sort((a,b)=>b.gapAtDate-a.gapAtDate);
 const eventDates=[...new Set([...baseline.timeline.map(x=>x.date),...plan.timeline.map(x=>x.date),...expenses.map(x=>x.date),asOf])].sort();
 let firstTimingOverrun=null,firstTotalOverrun=null;
 const actualTimeline=expenses.map(e=>({date:e.date,cost:expenseEUR(p,e)})).sort((a,b)=>a.date.localeCompare(b.date));
 const streams=[baseline.timeline,plan.timeline,actualTimeline],pointers=[0,0,0],running=[0,0,0];
 const timeline=eventDates.map(date=>{streams.forEach((rows,index)=>{while(pointers[index]<rows.length&&rows[pointers[index]].date<=date){running[index]=round(running[index]+rows[pointers[index]].cost);pointers[index]++;}});if(date<=asOf&&running[2]>running[0]+.005&&!firstTimingOverrun)firstTimingOverrun=date;if(date<=asOf&&running[2]>baseline.totalCost+.005&&!firstTotalOverrun)firstTotalOverrun=date;return {date,budget:running[0],forecast:running[1],actual:date<=asOf?running[2]:null};});

 const reasons=[];if(c.baseline){if(plan.days!==baseline.days)reasons.push(`Durée : ${plan.days} jours facturables prévus, contre ${baseline.days} au budget initial.`);if(plan.netDayRate!==baseline.netDayRate)reasons.push(`Salaire net par jour : ${plan.netDayRate} €, contre ${baseline.netDayRate} € au budget initial.`);if(plan.sellingDayRate!==baseline.sellingDayRate)reasons.push(`TJM vendu modifié : ${plan.sellingDayRate} €, contre ${baseline.sellingDayRate} € initialement.`);}else reasons.push('Budget initial non figé : validez-le pour conserver une référence indépendante des modifications.');
 if(c.baseline){const before=c.baseline.profile,now=profileFor(p,c),beforeFx=before.useBudgetFx?before.budgetEurPerUsd:1/before.usdPerEur,nowFx=now.useBudgetFx?now.budgetEurPerUsd:1/now.usdPerEur;if(Math.abs(beforeFx-nowFx)>1e-10)reasons.push(`Conversion des coûts USD : ${round(nowFx*10000)/10000} € pour 1 USD, contre ${round(beforeFx*10000)/10000} € au budget initial.`);if(before.vatRate!==now.vatRate)reasons.push(`TVA des postes prévus modifiée : ${now.vatRate} %, contre ${before.vatRate} % initialement.`);if(before.safetyMode!==now.safetyMode||before.safetyRate!==now.safetyRate)reasons.push('Le mode ou le taux de sécurité des coûts a été modifié.');if((plan.startDate!==baseline.startDate||plan.endDate!==baseline.endDate)&&plan.days===baseline.days)reasons.push('Les dates de mission ont changé à quantité de jours facturables identique : le rythme budgétaire est décalé.');const previousIds=new Set(baseline.items.map(i=>i.id)),currentIds=new Set(plan.items.map(i=>i.id)),added=plan.items.filter(i=>!previousIds.has(i.id)),removed=baseline.items.filter(i=>!currentIds.has(i.id));if(added.length)reasons.push('Nouveaux postes prévisionnels : '+added.slice(0,4).map(i=>i.name).join(', ')+'.');if(removed.length)reasons.push('Postes prévisionnels retirés : '+removed.slice(0,4).map(i=>i.name).join(', ')+'.');}
 if(billing.days){const average=round(billing.issued.reduce((s,i)=>s+i.days*i.dayRate,0)/billing.days);if(Math.abs(average-c.sellingDayRate)>=.01)reasons.push(`TJM moyen des jours facturés : ${average} € hors forfaits et heures supplémentaires, contre ${c.sellingDayRate} € dans la prévision.`);}
 if(actual>budgetAtDate+.005&&actual<=baseline.totalCost+.005)reasons.push('Les coûts saisis dépassent le rythme budgété à cette date, sans dépasser encore le budget total. Des frais payés en avance peuvent expliquer cet écart.');
 if(billing.forfaitCount)reasons.push(`${billing.forfaitCount} facture(s) au forfait sans jours renseignés : le coût par jour facturé peut être incomplet.`);
 return {consultant:c,plan,baseline,billing,expenses,actual,budgetAtDate,gapAtDate:round(actual-budgetAtDate),forecastGap:round(plan.totalCost-baseline.totalCost),totalOverrun:Math.max(0,round(actual-baseline.totalCost)),costPerBilledDay:billing.days?round(actual/billing.days):null,budgetForBilledDays:baseline.unitCost===null?null:round(baseline.unitCost*billing.days),balance:round(billing.billed-actual),remainingForecast:Math.max(0,round(plan.revenue-billing.billed)),categoryRows,timeline,firstTimingOverrun,firstTotalOverrun,reasons};
}
export function expenseEUR(p,e){return round(e.amount*(e.currency==='USD'?e.eurPerUsd:1));}
export function legacyTotals(p){if(!p.legacy)return {cost:0,revenue:0};const {months,investment,revenues,expenses}=p.legacy;const rows=revenues.map(r=>({...r,total:r.quantity*r.price*(r.frequency==='monthly'?months:1)}));return {revenue:sum(rows.map(r=>r.total)),cost:sum([investment,...expenses.map(e=>e.calculation==='percent'?(e.serviceId?rows.find(r=>r.id===e.serviceId)?.total||0:sum(rows.map(r=>r.total)))*e.rate/100:e.quantity*e.price*(e.frequency==='monthly'?months:1))])};}
export function projectDashboard(p,asOf=p.reportDate){const consultants=p.consultants.map(c=>consultantDashboard(p,c,asOf)),legacy=legacyTotals(p),billing=billingSummary(p,null,asOf);return {consultants,billing,forecastCost:sum([...consultants.map(x=>x.plan.totalCost),legacy.cost]),forecastRevenue:sum([...consultants.map(x=>x.plan.revenue),legacy.revenue]),initialCost:sum([...consultants.map(x=>x.baseline.totalCost),legacy.cost]),actual:sum(p.actualExpenses.filter(e=>e.date<=asOf).map(e=>expenseEUR(p,e))),legacy};}
export function itemValid(i,cats){return i&&text(i.id)&&text(i.name,200)&&cats.has(i.categoryId)&&nonnegative(i.amount)&&nonnegative(i.quantity)&&i.quantity<=1e6&&['EUR','USD'].includes(i.currency)&&['day','month','once','amortized','salary_pct'].includes(i.frequency)&&nonnegative(i.referenceDays)&&i.referenceDays>0&&i.referenceDays<=1e6&&(!i.date||validDate(i.date))&&['enabled','taxed','buffered'].every(k=>typeof i[k]==='boolean');}
function profileValid(b,cats){return b&&text(b.name)&&b.name.trim()&&validDate(b.startDate)&&validDate(b.endDate)&&datesBetween(b.startDate,b.endDate).length>0&&(b.daysOverride===null||nonnegative(b.daysOverride))&&['offDays','extraDays','netDayRate','markupPct','vatRate','safetyRate'].every(k=>nonnegative(b[k]))&&b.markupPct<=1000&&b.vatRate<=100&&b.safetyRate<=100&&Number.isFinite(b.usdPerEur)&&b.usdPerEur>0&&Number.isFinite(b.budgetEurPerUsd)&&b.budgetEurPerUsd>0&&typeof b.useBudgetFx==='boolean'&&['none','add','included'].includes(b.safetyMode)&&text(b.notes,10000)&&Array.isArray(b.items)&&b.items.length<=200&&b.items.every(i=>itemValid(i,cats))&&new Set(b.items.map(i=>i.id)).size===b.items.length&&(b.daysOverride!==null||b.offDays<=weekdaysBetween(dateNumber(b.startDate),dateNumber(b.endDate)));}
export function projectProblems(p){
 const fail=[];if(!p||p.version!==4||!text(p.id)||!p.id||!text(p.name)||!p.name.trim()||!text(p.client)||!validDate(p.reportDate))return ['Projet invalide.'];
 if(!Array.isArray(p.categories)||!p.categories.length||p.categories.length>100||p.categories.some(c=>!c||!text(c.id)||!text(c.name,80)||!c.name.trim()||!/^#[0-9a-f]{6}$/i.test(c.color)))return ['Catégories invalides.'];
 const cats=new Set(p.categories.map(c=>c.id));if(cats.size!==p.categories.length||!cats.has('other')||!cats.has(p.salaryCategoryId))return ['Vérifiez les catégories.'];
 if(!profileValid(p.budget,cats))fail.push('Vérifiez le budget, ses dates et ses postes de coûts.');
 for(const key of ['consultants','actualExpenses','invoices'])if(!Array.isArray(p[key])||p[key].length>(key==='consultants'?100:5000))return ['Nombre de lignes invalide.'];
 const ids=new Set(p.consultants.map(c=>c?.id));if(ids.size!==p.consultants.length)return ['Identifiants de consultants dupliqués.'];
 for(const c of p.consultants){if(!c||!text(c.id)||!text(c.name)||!text(c.role)||!datesBetween(c.startDate,c.endDate).length||!['offDays','extraDays','sellingDayRate','overtimeHours','overtimeSellingRate','overtimeCostRate'].every(k=>nonnegative(c[k]))||(c.daysOverride!==null&&!nonnegative(c.daysOverride))||(c.netDayRate!==null&&!nonnegative(c.netDayRate))||(c.markupPct!==null&&(!nonnegative(c.markupPct)||c.markupPct>1000))||!Array.isArray(c.extras)||c.extras.some(i=>!itemValid(i,cats))||(c.customBudget!==null&&!profileValid(c.customBudget,cats)))fail.push('Vérifiez les dates, tarifs et coûts de chaque consultant.');else if(c.daysOverride===null&&c.offDays>weekdaysBetween(dateNumber(c.startDate),dateNumber(c.endDate)))fail.push(`${c.name} : trop de jours non facturables.`);if(c.baseline){if(!profileValid(c.baseline.profile,cats)||!c.baseline.consultant||c.baseline.consultant.baseline||c.baseline.consultant.id!==c.id||!validProject4({...p,budget:c.baseline.profile,salaryCategoryId:c.baseline.salaryCategoryId,consultants:[{...c.baseline.consultant,baseline:null}],actualExpenses:[],invoices:[],legacy:null}))fail.push('Budget initial invalide.');}}
 for(const e of p.actualExpenses)if(!e||!text(e.id)||!ids.has(e.consultantId)||!cats.has(e.categoryId)||!validDate(e.date)||!text(e.title)||!text(e.note,3000)||!amount(e.amount)||!['EUR','USD'].includes(e.currency)||!Number.isFinite(e.eurPerUsd)||e.eurPerUsd<=0||e.eurPerUsd>100000)fail.push('Dépense réelle invalide.');
 const numbers=new Set();for(const i of p.invoices){if(!i||!text(i.id)||!text(i.number)||!i.number.trim()||!ids.has(i.consultantId)||!Object.hasOwn(STATUSES,i.status)||(!validDate(i.issueDate)&&['sent','awaiting_payment','paid'].includes(i.status))||(i.issueDate&&!validDate(i.issueDate))||(i.dueDate&&!validDate(i.dueDate))||!validDate(i.periodStart)||!validDate(i.periodEnd)||i.periodEnd<i.periodStart||!['days','dayRate','overtimeHours','hourRate'].every(k=>nonnegative(i[k]))||!amount(i.extraHT)||invoiceTotal(i)<0||!text(i.note,3000)||!Array.isArray(i.payments)||i.payments.some(x=>!x||!text(x.id)||!validDate(x.date)||!nonnegative(x.amount)||!x.amount)||paymentsAt(i)>invoiceTotal(i)+.005)fail.push('Vérifiez les dates, montants et paiements des factures.');else{const n=i.number.trim().toLocaleLowerCase();if(numbers.has(n))fail.push('Deux factures ont le même numéro.');numbers.add(n);if(['sent','awaiting_payment','paid'].includes(i.status)&&invoiceTotal(i)<=0)fail.push('Une facture émise doit avoir un montant HT positif.');if(i.dueDate&&i.issueDate&&i.dueDate<i.issueDate)fail.push('L’échéance ne peut pas précéder l’émission.');if(i.status==='paid'&&paymentsAt(i)<invoiceTotal(i)-.005)fail.push('Une facture payée doit avoir ses paiements renseignés.');if(i.status==='to_send'&&i.payments.length)fail.push('Une facture non envoyée ne peut pas avoir de paiement.');}}
 for(const key of ['actualExpenses','invoices'])if(new Set(p[key].map(x=>x.id)).size!==p[key].length)fail.push('Identifiants de lignes dupliqués.');
 if(p.legacy){const l=p.legacy;if(!Number.isInteger(l.months)||l.months<1||l.months>120||!nonnegative(l.investment)||!Array.isArray(l.revenues)||!Array.isArray(l.expenses)||l.revenues.some(r=>!r||!nonnegative(r.quantity)||!nonnegative(r.price)||!['once','monthly'].includes(r.frequency))||l.expenses.some(x=>!x||!['amount','percent'].includes(x.calculation)||!['once','monthly'].includes(x.frequency)||!['quantity','price','rate'].every(k=>nonnegative(x[k]))))fail.push('Anciennes lignes de budget invalides.');}
 return [...new Set(fail)];
}
export function validProject4(p){try{return projectProblems(p).length===0;}catch{return false;}}
export function budgetFromModel(m){const b=newBudget();b.name=m.name;b.notes=m.notes||'';for(const k of ['usdPerEur','useBudgetFx','budgetEurPerUsd','vatRate','safetyMode','safetyRate'])b[k]=m[k];b.suggestedSellingRate=m.suggestedRate||0;b.items=m.lines.map(l=>newItem({...copy(l),id:l.id,categoryId:l.category,frequency:l.basis==='day'?'day':l.basis==='once'?'once':'amortized'}));return b;}
export function migrateV3(old){if(old?.version===4)return validProject4(old)?copy(old):null;if(!old||![2,3].includes(old.version))return null;const p=newProject();p.name=old.name||p.name;const period=projectPeriod({...old,startDate:old.startDate||todayISO()});p.budget.startDate=period.startDate;p.budget.endDate=period.endDate;const sourceModel=old.defaultCostModel||old.consultants?.find(c=>c.costModel)?.costModel;if(sourceModel){const b=budgetFromModel(sourceModel);p.budget={...b,startDate:period.startDate,endDate:period.endDate};}
 p.legacy={months:old.months,investment:old.investment||0,revenues:copy(old.revenues||[]),expenses:copy((old.expenses||[]).filter(e=>!old.consultants?.some(c=>c.id===e.serviceId)))};
 for(const c of old.consultants||[]){const profile=c.costModel?budgetFromModel(c.costModel):{...newBudget(),items:[]};profile.netDayRate=0;if(c.purchaseDayRate)profile.items.push(newItem({name:'Achat / rémunération non ventilé (import)',categoryId:'contractors',amount:c.purchaseDayRate,frequency:'day'}));const next={...newConsultant(p),id:c.id,name:c.name,startDate:c.startDate,endDate:c.endDate,offDays:c.offDays,extraDays:c.extraDays,sellingDayRate:c.sellingDayRate,overtimeHours:c.overtimeHours,overtimeSellingRate:c.overtimeSellingRate,overtimeCostRate:c.overtimePurchaseRate,customBudget:profile,legacyPurchaseRate:c.purchaseDayRate};for(const e of (old.expenses||[]).filter(e=>e.serviceId===c.id)){let amount=e.price,frequency=e.frequency==='monthly'?'month':'once';if(e.calculation==='percent'){const days=weekdaysBetween(dateNumber(c.startDate),dateNumber(c.endDate))-c.offDays+c.extraDays;amount=(days*c.sellingDayRate+c.overtimeHours*c.overtimeSellingRate)*e.rate/100;frequency='once';}else if(frequency==='month'){amount=e.quantity*e.price*old.months;frequency='once';}else amount=e.quantity*e.price;next.extras.push(newItem({id:e.id,name:e.name,categoryId:e.category,amount,frequency}));}p.consultants.push(next);next.baseline=freezeBaseline(p,next);}
 return validProject4(p)?p:null;
}
export function removeCategory(p,id){if(id==='other')return;const reassign=items=>items.forEach(i=>{if(i.categoryId===id)i.categoryId='other';});reassign(p.budget.items);if(p.salaryCategoryId===id)p.salaryCategoryId='other';for(const c of p.consultants){reassign(c.extras);if(c.customBudget)reassign(c.customBudget.items);if(c.baseline){reassign(c.baseline.profile.items);reassign(c.baseline.consultant.extras);if(c.baseline.salaryCategoryId===id)c.baseline.salaryCategoryId='other';if(c.baseline.consultant.customBudget)reassign(c.baseline.consultant.customBudget.items);}}p.actualExpenses.forEach(e=>{if(e.categoryId===id)e.categoryId='other';});p.categories=p.categories.filter(c=>c.id!==id);}
